// sandbox.rs — Agent process sandboxing (v0.14.0; Windows Job Objects v0.16.4).
//
// Wraps a SpawnRequest to apply OS-level sandboxing before the agent process
// starts.  On macOS this uses `sandbox-exec` with a generated `.sb` profile;
// on Linux it uses `bwrap` (bubblewrap) when available; on Windows it uses
// Job Objects (see `sandbox_windows.rs`).
//
// Sandboxing is opt-in: `SandboxPolicy::disabled()` is the default and
// passes requests through unchanged.  Enable via `[sandbox] enabled = true`
// in `.ta/workflow.toml`.
//
// ## macOS sandbox-exec
//
// The profile is generated by `seatbelt.rs` (v0.17.12.7): read-allow with
// targeted denies, deny-default writes, a mach-lookup allowlist, and loopback
// closed except for the per-goal egress proxy and the mediation socket.
//
// ## Linux bubblewrap (bwrap)
//
// When `bwrap` is on PATH, wraps the agent with filesystem namespacing:
// - Bind-mounts declared readable paths as ro
// - Bind-mounts the working dir as rw
// - Creates tmpfs for /tmp
// - Network: unshared by default (--unshare-net) unless allow_network is non-empty
//
// ## Windows Job Objects
//
// Creates a Job Object with `JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE`.  The agent
// process (and all its children) are assigned to the Job Object after spawn.
// When TA exits or the guard is dropped, the entire process tree is killed.
// Note: Job Objects do not restrict filesystem access — that requires AppContainer.

#[cfg(target_os = "macos")]
use std::path::Path;
use std::path::PathBuf;

use crate::adapter::SpawnRequest;
use crate::sandbox_windows::WindowsJobObjectGuard;

/// Absolute path: never resolved through a `PATH` the agent could have influenced.
#[cfg(target_os = "macos")]
pub const SANDBOX_EXEC: &str = "/usr/bin/sandbox-exec";

/// A resolved sandbox policy derived from `SandboxConfig`.
#[derive(Debug, Clone)]
pub struct SandboxPolicy {
    /// Whether sandboxing is active.
    pub enabled: bool,

    /// Which sandbox implementation to use.
    pub provider: SandboxProvider,

    /// Paths the agent may read (in addition to system libraries and its workspace).
    pub allow_read: Vec<PathBuf>,

    /// Paths the agent may write (workspace root is always included).
    pub allow_write: Vec<PathBuf>,

    /// Network destinations the agent may reach.
    /// If empty, all outbound network is blocked.
    /// If contains "*", all outbound network is allowed.
    pub allow_network: Vec<String>,

    /// Paths that are denied for read and write even when an allow rule
    /// covers a parent (the project `.ta/` tree, the TA state directory,
    /// credential stores). Emitted after the broad allows so deny wins
    /// (v0.17.12.6). Bubblewrap never mounts these, so it needs no rule.
    pub deny_paths: Vec<PathBuf>,

    /// Per-goal read-write paths granted after `deny_paths` (the goal's
    /// staging dir sits inside the denied `.ta/` tree, and the per-goal agent
    /// home sits inside the denied state dir).
    pub goal_paths: Vec<PathBuf>,

    /// Unix socket files the agent may connect to (the per-goal mediation
    /// endpoint). The only IPC channel into the control plane.
    pub unix_sockets: Vec<PathBuf>,

    /// Loopback port of the per-goal egress proxy (v0.17.12.7). The only
    /// loopback address the macOS profile lets the agent reach; hostname policy
    /// lives in the proxy.
    pub egress_proxy_port: Option<u16>,

    /// Linux only (v0.17.12.8): the Unix socket a host-side relay listens on and
    /// forwards to the egress proxy. The network namespace has no route to host
    /// loopback, so this bind-mounted socket is the only way out; an
    /// in-namespace relay serves `egress_proxy_port` and forwards to it.
    pub egress_unix_socket: Option<PathBuf>,

    /// Windows-only launch inputs (v0.17.12.9): the egress relay pipe, Job
    /// Object limits, and the directories to grant the container read access to.
    pub windows: crate::windows_policy::WindowsLaunch,

    /// Tag the macOS profile appends to every denial in the unified log, so
    /// violations can be attributed to this goal.
    pub violation_tag: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SandboxProvider {
    /// No sandboxing — pass request through unchanged.
    None,
    /// macOS sandbox-exec (Seatbelt).
    MacosSandboxExec,
    /// Linux bubblewrap namespaces plus Landlock and seccomp applied by the
    /// `ta-sandbox-exec` helper inside them.
    LinuxBwrap,
    /// Linux without usable namespaces: Landlock and seccomp only. Filesystem
    /// confinement holds; there is no network namespace, so TCP is limited by
    /// Landlock ABI 4+ where the kernel has it.
    LinuxLandlock,
    /// Windows Job Objects — process-tree teardown on TA exit.
    ///
    /// Does not restrict filesystem access (AppContainer handles that).
    /// Applied post-spawn via `SandboxPolicy::post_spawn_apply()`.
    WindowsJobObject,
    /// Windows AppContainer — filesystem + network isolation (v0.16.4.2).
    ///
    /// Spawns the agent inside a named AppContainer that:
    ///   - Restricts filesystem writes to the staging workspace (via DACL grant)
    ///   - Blocks outbound network unless `internetClient` capability is declared
    ///
    /// A Job Object is also attached post-spawn for process-tree teardown.
    /// Applied pre-spawn via `SandboxPolicy::pre_spawn_appcontainer()`.
    WindowsAppContainer,
}

impl SandboxPolicy {
    /// A no-op policy (sandboxing disabled).
    pub fn disabled() -> Self {
        Self {
            enabled: false,
            provider: SandboxProvider::None,
            allow_read: Vec::new(),
            allow_write: Vec::new(),
            allow_network: Vec::new(),
            deny_paths: Vec::new(),
            goal_paths: Vec::new(),
            unix_sockets: Vec::new(),
            egress_proxy_port: None,
            egress_unix_socket: None,
            windows: Default::default(),
            violation_tag: None,
        }
    }

    /// Detect which provider is available on the current platform.
    ///
    /// On macOS: always use sandbox-exec (built-in).
    /// On Linux: bubblewrap when it works here, else Landlock-only, else none
    /// (see `linux_probe`).
    /// On Windows: always use Job Objects (built-in; no external tool needed).
    /// Elsewhere: no sandboxing.
    pub fn detect_provider() -> SandboxProvider {
        #[cfg(target_os = "macos")]
        {
            SandboxProvider::MacosSandboxExec
        }
        #[cfg(target_os = "linux")]
        {
            match crate::linux_probe::cached().selection() {
                crate::linux_probe::Selection::Bwrap => SandboxProvider::LinuxBwrap,
                crate::linux_probe::Selection::LandlockOnly => SandboxProvider::LinuxLandlock,
                crate::linux_probe::Selection::None => SandboxProvider::None,
            }
        }
        #[cfg(target_os = "windows")]
        {
            // Prefer AppContainer (filesystem + network isolation) over Job Objects
            // (process-tree teardown only).  AppContainer requires Windows 8+; the
            // binary only loads there, so appcontainer_available() is a runtime guard
            // against restricted execution environments (e.g., nested containers).
            if crate::sandbox_windows::appcontainer_available() {
                SandboxProvider::WindowsAppContainer
            } else {
                SandboxProvider::WindowsJobObject
            }
        }
        #[cfg(not(any(target_os = "macos", target_os = "linux", target_os = "windows")))]
        {
            SandboxProvider::None
        }
    }

    /// Apply this policy to a SpawnRequest, wrapping it in the sandbox.
    ///
    /// If disabled or provider is None, returns the request unchanged.
    ///
    /// For `WindowsJobObject`, this is a no-op — Job Objects are applied
    /// after the process is spawned via `post_spawn_apply()`.
    pub fn apply(&self, request: SpawnRequest) -> SpawnRequest {
        if !self.enabled || self.provider == SandboxProvider::None {
            return request;
        }

        match self.provider {
            SandboxProvider::MacosSandboxExec => self.apply_macos(request),
            SandboxProvider::LinuxBwrap | SandboxProvider::LinuxLandlock => {
                match self.try_apply_linux(request.clone()) {
                    Ok(r) => r,
                    Err(msg) => {
                        // Fail closed: never hand back the unwrapped request. A
                        // command that cannot start is visible; an unsandboxed
                        // agent that looks sandboxed is not.
                        tracing::error!(error = %msg, "Linux sandbox could not be applied");
                        let mut r = request;
                        r.args = vec![
                            "-c".into(),
                            "echo \"ta: $1\" >&2; exit 126".into(),
                            "ta".into(),
                            msg,
                        ];
                        r.command = "/bin/sh".into();
                        r
                    }
                }
            }
            // Job Objects are applied post-spawn; the SpawnRequest is unchanged.
            SandboxProvider::WindowsJobObject => request,
            // The container itself is created pre-spawn (pre_spawn_appcontainer). Here the
            // command is only wrapped with the in-container relay helper when the
            // egress pipe is in use.
            SandboxProvider::WindowsAppContainer => self.apply_windows_relay(request),
            SandboxProvider::None => request,
        }
    }

    /// Set up an AppContainer profile before the agent process is spawned (Windows only).
    ///
    /// Returns `Some(guard)` when the provider is `WindowsAppContainer` and setup succeeds.
    /// Returns `None` when not on Windows, provider is not `WindowsAppContainer`, or disabled.
    ///
    /// The guard must be kept alive for the agent's entire lifetime — it is passed to
    /// `sandboxed_spawn` to launch the process inside the container, and its Drop
    /// implementation deletes the profile.
    ///
    /// `goal_id` is used to derive a unique container name (first 8 hex chars).
    pub fn pre_spawn_appcontainer(
        &self,
        staging_path: &std::path::Path,
        goal_id: &str,
    ) -> Result<Option<crate::sandbox_windows::WindowsAppContainerGuard>, String> {
        if !self.enabled || self.provider != SandboxProvider::WindowsAppContainer {
            return Ok(None);
        }
        let container_name = crate::windows_policy::container_name(goal_id);
        // Direct network (`internetClient`) is granted only when there is no relay.
        // With the relay, the pipe is the sole path out, so a failed relay means
        // no network rather than unproxied network.
        let allow_network = !self.allow_network.is_empty() && self.windows.egress_pipe.is_none();
        let mut guard = crate::sandbox_windows::WindowsAppContainerGuard::new(
            &container_name,
            staging_path,
            allow_network,
        )?;
        self.grant_toolchain_reads(&mut guard, goal_id);
        Ok(Some(guard))
    }

    /// Grant the container read+execute on the toolchain directories, with a
    /// ledger entry per grant. A failed or skipped grant is logged, never fatal:
    /// the agent then fails visibly on the missing tool instead of TA widening
    /// access.
    fn grant_toolchain_reads(
        &self,
        guard: &mut crate::sandbox_windows::WindowsAppContainerGuard,
        goal_id: &str,
    ) {
        let Some(state_dir) = &self.windows.state_dir else {
            return;
        };
        let extras: Vec<_> = self
            .windows
            .extra_read_dirs
            .iter()
            .map(|p| crate::windows_policy::ToolchainGrant {
                path: p.clone(),
                reason: "required by the agent launch".to_string(),
            })
            .collect();
        let owner: Vec<String> = self
            .allow_read
            .iter()
            .map(|p| p.display().to_string())
            .collect();
        let plan = crate::windows_policy::plan_toolchain_grants(
            &|k| std::env::var(k).ok(),
            &extras,
            &owner,
            &self.deny_paths,
            &|p| p.exists(),
        );
        for (path, why) in &plan.skipped {
            tracing::warn!(
                path = %path.display(),
                reason = %why,
                "toolchain directory not granted to the AppContainer"
            );
        }
        let ledger = crate::windows_policy::GrantLedger::in_dir(state_dir);
        let (applied, errors) = guard.grant_toolchain_reads(goal_id, &plan, &ledger);
        for e in &errors {
            tracing::warn!(
                error = %e,
                ledger = %ledger.path().display(),
                "toolchain ACL grant failed; the agent may not find that tool. \
                 `ta doctor --fix` removes any grant left behind"
            );
        }
        tracing::info!(
            granted = applied,
            skipped = plan.skipped.len(),
            failed = errors.len(),
            goal_id = goal_id,
            "AppContainer toolchain read grants"
        );
    }

    /// Wrap the command with `ta-sandbox-exec` so the agent reaches the egress
    /// proxy through the in-container loopback listener and the named pipe.
    fn apply_windows_relay(&self, request: SpawnRequest) -> SpawnRequest {
        let (Some(pipe), Some(port)) = (&self.windows.egress_pipe, self.egress_proxy_port) else {
            return request;
        };
        let Some(helper) = crate::linux_probe::find_helper() else {
            // Fail closed: without the helper the agent would have no network
            // path, so make the cause the visible failure.
            tracing::error!(
                helper = crate::linux_probe::HELPER_BIN_NAME,
                "sandbox helper not found; the agent would start without an egress path"
            );
            let mut r = request;
            r.args = vec![
                "/c".into(),
                format!(
                    "echo ta: the sandbox helper {} was not found next to ta.exe. Reinstall TA \
                     or set {} to its path. 1>&2 & exit /b 126",
                    crate::linux_probe::HELPER_BIN_NAME,
                    crate::linux_probe::HELPER_ENV
                ),
            ];
            r.command = "cmd.exe".into();
            return r;
        };
        let args = crate::windows_relay::HelperArgs {
            egress_pipe: Some(pipe.clone()),
            egress_port: Some(port),
            command: std::iter::once(request.command.clone())
                .chain(request.args.iter().cloned())
                .collect(),
        };
        let mut r = request;
        r.command = helper.program.display().to_string();
        r.args = helper
            .prefix_args
            .into_iter()
            .chain(args.to_args())
            .collect();
        r
    }

    /// Create a Job Object guard and assign the agent process to it (Windows only).
    ///
    /// Call immediately after spawning the agent process. Hold the returned guard alive for
    /// the duration of the agent run — dropping it closes the Job Object handle and kills
    /// the entire process tree (`KILL_ON_JOB_CLOSE`).
    ///
    /// Activates for both `WindowsJobObject` and `WindowsAppContainer` providers so
    /// process-tree teardown works alongside AppContainer filesystem/network isolation.
    ///
    /// Returns `None` when sandboxing is disabled, provider is not a Windows variant,
    /// or Job Object creation fails (a structured warning is logged in that case).
    pub fn post_spawn_apply(&self, pid: u32) -> Option<WindowsJobObjectGuard> {
        // Attach a Job Object for process-tree teardown on both WindowsJobObject
        // and WindowsAppContainer providers (AppContainer + Job Object work together).
        if !self.enabled
            || !matches!(
                self.provider,
                SandboxProvider::WindowsJobObject | SandboxProvider::WindowsAppContainer
            )
        {
            return None;
        }

        let limits = self.windows.job_limits.unwrap_or_default();
        // Under the Job Object provider the job is the confinement, so a failure is an
        // error; under AppContainer it is defence in depth.
        let confinement = self.provider == SandboxProvider::WindowsJobObject;
        let guard = match WindowsJobObjectGuard::with_limits(&limits) {
            Ok(g) => g,
            Err(e) => {
                if confinement {
                    tracing::error!(
                        error = %e,
                        limits = %limits.describe(),
                        "Failed to create the Windows Job Object that confines this agent. \
                         Its process tree will not be limited or auto-killed."
                    );
                } else {
                    tracing::warn!(
                        error = %e,
                        limits = %limits.describe(),
                        "Failed to create the Windows Job Object; the AppContainer still \
                         confines the agent but its process tree will not be limited or \
                         auto-killed on TA exit."
                    );
                }
                return None;
            }
        };

        if let Err(e) = guard.assign_process(pid) {
            tracing::warn!(
                pid = pid,
                error = %e,
                "Failed to assign agent process to Job Object — process tree teardown \
                 will not be enforced."
            );
            return None;
        }

        tracing::info!(
            pid = pid,
            "Agent process assigned to Windows Job Object (KILL_ON_JOB_CLOSE)"
        );
        Some(guard)
    }

    /// Wrap the request in `sandbox-exec -p <profile> -- <cmd> <args>`.
    #[cfg(target_os = "macos")]
    fn apply_macos(&self, mut request: SpawnRequest) -> SpawnRequest {
        let profile = self.generate_macos_profile(&request.working_dir);

        // Build: sandbox-exec -p "<profile>" -- <original_cmd> <original_args>
        let mut new_args = vec![
            "-p".to_string(),
            profile,
            "--".to_string(),
            request.command.clone(),
        ];
        new_args.extend(request.args.iter().cloned());

        request.command = SANDBOX_EXEC.to_string();
        request.args = new_args;
        request
    }

    #[cfg(not(target_os = "macos"))]
    fn apply_macos(&self, request: SpawnRequest) -> SpawnRequest {
        request
    }

    /// Generate the macOS Seatbelt (.sb) profile string (see `seatbelt.rs`).
    #[cfg(target_os = "macos")]
    fn generate_macos_profile(&self, working_dir: &Path) -> String {
        crate::seatbelt::generate(self, working_dir)
    }

    /// Apply this policy, reporting why when a Linux provider cannot be applied.
    /// Callers that can surface an error (`ta run`) use this instead of `apply`.
    pub fn try_apply(&self, request: SpawnRequest) -> Result<SpawnRequest, String> {
        if self.enabled
            && matches!(
                self.provider,
                SandboxProvider::LinuxBwrap | SandboxProvider::LinuxLandlock
            )
        {
            return self.try_apply_linux(request);
        }
        Ok(self.apply(request))
    }

    /// Wrap the request for the Linux providers, or say exactly why not.
    ///
    /// Never falls back to running the agent unwrapped: the error names the
    /// missing piece and what to do about it.
    #[cfg(target_os = "linux")]
    pub fn try_apply_linux(&self, request: SpawnRequest) -> Result<SpawnRequest, String> {
        let probe = crate::linux_probe::cached();
        let helper = crate::linux_probe::find_helper().ok_or_else(|| {
            format!(
                "the sandbox helper `{}` was not found next to this executable and `ta` is not \
                 the running binary. Reinstall TA, or set {} to the helper path.",
                crate::linux_probe::HELPER_BIN_NAME,
                crate::linux_probe::HELPER_ENV
            )
        })?;
        match self.provider {
            SandboxProvider::LinuxBwrap => match &probe.bwrap {
                crate::linux_probe::BwrapStatus::Usable { path, .. } => {
                    Ok(crate::linux_bwrap::wrap_bwrap(request, self, path, &helper))
                }
                _ => Err(format!(
                    "bubblewrap was selected but is not usable. {}",
                    probe.findings().join(" ")
                )),
            },
            SandboxProvider::LinuxLandlock => {
                if probe.landlock.abi().is_none() {
                    return Err(format!(
                        "Landlock was selected but is not available: {}",
                        probe.findings().join(" ")
                    ));
                }
                Ok(crate::linux_bwrap::wrap_landlock_only(
                    request, self, &helper,
                ))
            }
            _ => Ok(request),
        }
    }

    /// Non-Linux hosts have no Linux provider.
    #[cfg(not(target_os = "linux"))]
    pub fn try_apply_linux(&self, _request: SpawnRequest) -> Result<SpawnRequest, String> {
        Err("the Linux sandbox providers run on Linux only".to_string())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;
    use std::path::Path;

    fn dummy_request(working_dir: &Path) -> SpawnRequest {
        SpawnRequest {
            command: "claude".to_string(),
            args: vec!["--print".to_string(), "hello".to_string()],
            env: HashMap::new(),
            working_dir: working_dir.to_path_buf(),
            stdin_mode: crate::adapter::StdinMode::Null,
            stdout_mode: crate::adapter::StdoutMode::Inherited,
            clear_env: false,
        }
    }

    #[test]
    fn disabled_policy_passthrough() {
        let policy = SandboxPolicy::disabled();
        let req = dummy_request(std::path::Path::new("/tmp/staging"));
        let wrapped = policy.apply(req.clone());
        assert_eq!(wrapped.command, req.command);
        assert_eq!(wrapped.args, req.args);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn macos_profile_contains_working_dir() {
        let policy = SandboxPolicy {
            enabled: true,
            provider: SandboxProvider::MacosSandboxExec,
            allow_read: Vec::new(),
            allow_write: Vec::new(),
            allow_network: Vec::new(),
            deny_paths: Vec::new(),
            goal_paths: Vec::new(),
            unix_sockets: Vec::new(),
            egress_proxy_port: None,
            egress_unix_socket: None,
            windows: Default::default(),
            violation_tag: None,
        };
        let working_dir = std::path::Path::new("/tmp/ta-staging/abc123");
        let profile = policy.generate_macos_profile(working_dir);
        assert!(
            profile.contains("/tmp/ta-staging/abc123"),
            "profile should include workspace"
        );
        assert!(
            profile.contains("(deny default)"),
            "profile should deny by default"
        );
        assert!(
            !profile.contains("(allow network"),
            "no network allow rules when allow_network is empty"
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn macos_sandbox_exec_wraps_command() {
        let policy = SandboxPolicy {
            enabled: true,
            provider: SandboxProvider::MacosSandboxExec,
            allow_read: Vec::new(),
            allow_write: Vec::new(),
            allow_network: vec!["api.anthropic.com".to_string()],
            deny_paths: Vec::new(),
            goal_paths: Vec::new(),
            unix_sockets: Vec::new(),
            egress_proxy_port: None,
            egress_unix_socket: None,
            windows: Default::default(),
            violation_tag: None,
        };
        let req = dummy_request(std::path::Path::new("/tmp/staging"));
        let wrapped = policy.apply(req);
        assert_eq!(wrapped.command, SANDBOX_EXEC);
        assert_eq!(wrapped.args[0], "-p");
        assert_eq!(wrapped.args[2], "--");
        assert_eq!(wrapped.args[3], "claude");
        assert_eq!(wrapped.args[4], "--print");
    }

    /// WindowsJobObject apply() is a no-op — Job Objects are applied post-spawn.
    #[test]
    fn windows_job_object_apply_does_not_wrap_command() {
        let policy = SandboxPolicy {
            enabled: true,
            provider: SandboxProvider::WindowsJobObject,
            allow_read: Vec::new(),
            allow_write: Vec::new(),
            allow_network: Vec::new(),
            deny_paths: Vec::new(),
            goal_paths: Vec::new(),
            unix_sockets: Vec::new(),
            egress_proxy_port: None,
            egress_unix_socket: None,
            windows: Default::default(),
            violation_tag: None,
        };
        let req = dummy_request(std::path::Path::new("/tmp/staging"));
        let wrapped = policy.apply(req.clone());
        assert_eq!(
            wrapped.command, req.command,
            "WindowsJobObject must not change the command"
        );
        assert_eq!(
            wrapped.args, req.args,
            "WindowsJobObject must not change the args"
        );
    }

    /// detect_provider() returns a Windows provider on Win10/Win11, macOS provider on macOS.
    #[test]
    fn detect_provider_windows() {
        let provider = SandboxPolicy::detect_provider();
        #[cfg(target_os = "windows")]
        // On Win10/Win11 (the supported range) AppContainer APIs are available, so
        // WindowsAppContainer is preferred. WindowsJobObject is the fallback for
        // environments where AppContainer is restricted (e.g. nested containers).
        assert!(
            provider == SandboxProvider::WindowsAppContainer
                || provider == SandboxProvider::WindowsJobObject,
            "Windows provider must be WindowsAppContainer or WindowsJobObject, got {:?}",
            provider
        );
        #[cfg(target_os = "macos")]
        assert_eq!(provider, SandboxProvider::MacosSandboxExec);
        // Linux returns LinuxBwrap (if bwrap present) or None — just verify no panic.
        #[cfg(not(any(target_os = "windows", target_os = "macos")))]
        let _ = provider;
    }

    /// post_spawn_apply returns None when sandboxing is disabled.
    #[test]
    fn post_spawn_apply_disabled_returns_none() {
        let policy = SandboxPolicy::disabled();
        let guard = policy.post_spawn_apply(1234);
        assert!(guard.is_none(), "disabled policy should return None");
    }

    /// post_spawn_apply returns None for non-WindowsJobObject providers.
    #[test]
    fn post_spawn_apply_non_windows_provider_returns_none() {
        let policy = SandboxPolicy {
            enabled: true,
            provider: SandboxProvider::MacosSandboxExec,
            allow_read: Vec::new(),
            allow_write: Vec::new(),
            allow_network: Vec::new(),
            deny_paths: Vec::new(),
            goal_paths: Vec::new(),
            unix_sockets: Vec::new(),
            egress_proxy_port: None,
            egress_unix_socket: None,
            windows: Default::default(),
            violation_tag: None,
        };
        let guard = policy.post_spawn_apply(1234);
        assert!(
            guard.is_none(),
            "non-WindowsJobObject provider should return None"
        );
    }

    /// post_spawn_apply with WindowsJobObject and an invalid PID:
    /// On Windows returns None (OpenProcess fails).
    /// On non-Windows returns None (assign_process is no-op but the guard
    /// IS returned for a valid-looking PID — so use an impossible PID).
    #[test]
    fn post_spawn_apply_windows_job_object_invalid_pid() {
        let policy = SandboxPolicy {
            enabled: true,
            provider: SandboxProvider::WindowsJobObject,
            allow_read: Vec::new(),
            allow_write: Vec::new(),
            allow_network: Vec::new(),
            deny_paths: Vec::new(),
            goal_paths: Vec::new(),
            unix_sockets: Vec::new(),
            egress_proxy_port: None,
            egress_unix_socket: None,
            windows: Default::default(),
            violation_tag: None,
        };
        // PID 0 / 0xFFFFFFFF are never valid on any platform.
        let guard = policy.post_spawn_apply(0);
        // On Windows: assign_process(0) fails → returns None.
        // On non-Windows: stub assign_process always Ok → Some(guard) is returned.
        // The key assertion: no panic.
        let _ = guard;
    }
}
